arguments.advancedArgs:
{
  "type": "object",
  "properties": {
    "existingNeedName": {
      "type": "string",
      "description": "The name (or partial name) of an already-existing training need category to attach this application to, e.g. 'Database & Data Management' - matches case-insensitively against the category list from getSelfTrainingNeeds' existingNeedCategories. Use this when the employee picks one of the categories already on file (UAC 3.2 - Training Need Type = 'Existing Need' on the real form) rather than describing something new. If more than one category matches, the tool returns status AMBIGUOUS with the candidates - ask the employee to pick one and retry with the exact name. Either existingNeedName or newNeedName must be provided, not both. Not required when calling purely to list ongoing goals (enableGoalObjectives: true, no goalTitle yet)."
    },
    "newNeedName": {
      "type": "string",
      "description": "The requested need, in the employee's own words, when what they need isn't already an existing category, e.g. 'Advanced Excel Macros' (UAC 3.3 - Training Need Type = 'New Need' on the real form, the 'Requested Need' field). Either existingNeedName or newNeedName must be provided, not both. Not required when calling purely to list ongoing goals (enableGoalObjectives: true, no goalTitle yet)."
    },
    "newNeedDescription": {
      "type": "string",
      "description": "A fuller description of the new requested need (the 'Requested Need Description' field on the real form). Optional even when newNeedName is given - only used alongside newNeedName, ignored for existingNeedName."
    },
    "enableGoalObjectives": {
      "type": "boolean",
      "description": "Set true when the employee wants to link their training need's objective to one of their ongoing performance goals but hasn't picked which one yet (mirrors the real form's 'Enable Goal Objectives' checkbox, which loads the goal list straight into the Objectives dropdown). When true and goalTitle is not yet provided, this tool returns status GOALS_LISTED with the employee's current ongoing goals (ongoingGoals: [{goalTitle, goalCode}]) instead of submitting anything - present the titles, get the employee's choice, then call this tool again with goalTitle set to their exact choice (plus existingNeedName/newNeedName and the other required fields, since nothing is submitted on this listing call). Do not set this once goalTitle is already known - pass goalTitle directly instead. This is always safe to call on its own since it only reads the goal list, nothing is written."
    },
    "objective": {
      "type": "string",
      "description": "The objective of this training need, in the employee's own words - OR link to one of the employee's ongoing performance goals via goalTitle instead (the real form's 'Enable Goal Objectives' checkbox switches this from free text to a goal picker - only one of the two is used). Whether objective/goalTitle is actually mandatory is a per-client Training & Development configuration setting (IsObjectiveMandatory) and can change - do not assume it's required and do not insist on it upfront if the employee doesn't have one in mind yet. Call this tool with whatever is known; if ValidateNeedApplication rejects the submission with 'Please specify the objective.', that confirms it's mandatory for this org - ask the employee for it then and call this tool again with the same arguments plus objective (or goalTitle) filled in."
    },
    "goalTitle": {
      "type": "string",
      "description": "The title of one of the employee's ongoing performance goals to link this training need's objective to, instead of writing a free-text objective (the real form's 'Enable Goal Objectives' checkbox, switching the Objective field from a text box to a goal-picker dropdown). Matches case-insensitively against the employee's live ongoing-goals list. If you don't already know the employee's exact ongoing goal titles, first call this tool with enableGoalObjectives: true and no goalTitle to get the current list (status GOALS_LISTED) - do not guess or invent a title. If more than one ongoing goal shares that exact title (confirmed to happen in real data), the tool returns AMBIGUOUS and it's simpler to just provide the objective argument instead. Do not use this unless the employee explicitly wants to link the need to an existing goal - a plain-text objective is the default path."
    },
    "relevanceToJob": {
      "type": "string",
      "description": "How this training need relates to the employee's job. Whether this is mandatory is a per-client Training & Development configuration setting (IsRelToJobMandatory) and can change between orgs - do not assume it's required and do not ask the employee for it upfront. Call this tool with whatever is known; if ValidateNeedApplication rejects the submission with 'Please specify the relevance to job.', that confirms it's mandatory for this org - ask for it then and call this tool again with the same arguments plus relevanceToJob filled in."
    },
    "benefitToEmployee": {
      "type": "string",
      "description": "The benefit of this training need to the employee. Whether this is mandatory is a per-client Training & Development configuration setting (IsPotentialToYouMandatory) and can change between orgs - do not assume it's required and do not ask the employee for it upfront. Call this tool with whatever is known; if ValidateNeedApplication rejects the submission with 'Please specify the benefit to you.', that confirms it's mandatory for this org - ask for it then and call this tool again with the same arguments plus benefitToEmployee filled in."
    },
    "benefitToCompany": {
      "type": "string",
      "description": "The benefit of this training need to the company. Whether this is mandatory is a per-client Training & Development configuration setting (IsPotentialToCompMandatory) and can change between orgs - do not assume it's required and do not ask the employee for it upfront. Call this tool with whatever is known; if ValidateNeedApplication rejects the submission with 'Please specify the benefit to the company.', that confirms it's mandatory for this org - ask for it then and call this tool again with the same arguments plus benefitToCompany filled in."
    },
    "removeAttachments": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Whenever the user attaches a file, call this tool again on that same turn, with whatever arguments are already known - the chat hands this tool a file's contents only on the turn it was attached, so never just acknowledge a file, ask a question first, or call another tool instead; a file this tool never sees on its own turn has to be attached again. File names to take off this application, exactly as shown in the preview's attachments list or as attached in the chat - e.g. when the employee says 'remove images.png'. Attachments are never passed as arguments: every file the employee attaches in the chat is picked up automatically and added to the application (several files are allowed, in one message or across several). A removed file stays out on later calls even if the chat keeps listing it, so there is no need to send it again; attaching it again brings it back. A file this tool rejected for its type or size is already left out - never put it here. Never tell the employee to start a new chat to get rid of a file."
    },
    "replaceAttachments": {
      "type": "boolean",
      "description": "Set true when the employee attaches a new file to REPLACE the earlier one(s) ('use this document instead', 'replace the attachment with this'), on the call for the message that carries the new file: the file(s) attached in that message become the only attachments and every earlier file is left out. Leave unset when they are adding another file - files are added by default. If the new file was attached in an earlier message, use removeAttachments with the old file's name instead."
    },
    "confirmed": {
      "type": "boolean",
      "description": "Set true only after the employee has reviewed a summary of this exact application (need, objective/goal, relevance to job, benefits, attachments) and explicitly agreed to submit it. Leave unset/false on the first call - the tool returns status CONFIRMATION_REQUIRED with a preview and the server's own confirmation prompt (mirrors the real form's 'Are you sure you want to submit this training need?' dialog, shown right before Save) instead of submitting anything. Nothing is validated or saved until this is true (attached files are uploaded as soon as they are attached, as on the real form, but only become part of the application when it is saved). Call this tool again with confirmed:true and the exact same arguments once the employee agrees."
    }
  },
  "required": []
}

raw.transformer:
(async function (data, args, reqOptions) {
  try {
    if (
      !BeaconBar.user?.metaData?.menus?.some(menu =>
        menu.includes("TNDV9/TrainingNeed/Index?mvc=1&bs=4&App=000001")
      )
    ) {
      return { error: true, message: "You do not have access to apply for a training need. Please contact HR Admin." };
    }

    const existingNeedName = args.existingNeedName ? String(args.existingNeedName).trim() : "";
    const newNeedName = args.newNeedName ? String(args.newNeedName).trim() : "";
    const newNeedDescription = args.newNeedDescription ? String(args.newNeedDescription).trim() : "";
    const objective = args.objective ? String(args.objective).trim() : "";
    const goalTitle = args.goalTitle ? String(args.goalTitle).trim() : "";
    const enableGoalObjectives = args.enableGoalObjectives === true || String(args.enableGoalObjectives).toLowerCase() === "true";
    const relevanceToJob = args.relevanceToJob ? String(args.relevanceToJob).trim() : "";
    const benefitToEmployee = args.benefitToEmployee ? String(args.benefitToEmployee).trim() : "";
    const benefitToCompany = args.benefitToCompany ? String(args.benefitToCompany).trim() : "";

    const headers = new Headers();
    headers.append("Accept", "*/*");
    headers.append("Content-Type", "application/json");
    headers.append("x-requested-with", "XMLHttpRequest");

    async function postJson(path, body) {
      const url = `${window.origin}/${reqOptions.sl}/${path}`;
      let response;
      try {
        response = await fetch(url, {
          method: "POST",
          headers: headers,
          body: body !== undefined ? JSON.stringify(body) : undefined
        });
      } catch (networkError) {
        throw new Error(`Could not reach ${path}: ${networkError.message}`);
      }
      const rawText = await response.text();
      let parsed = null;
      try {
        parsed = rawText ? JSON.parse(rawText) : null;
      } catch (parseError) {
        throw new Error(`${path} returned a non-JSON response (HTTP ${response.status}).`);
      }
      if (!response.ok) {
        const detail = (parsed && (parsed.Message || (parsed.Status && parsed.Status.Message))) || rawText.slice(0, 200);
        throw new Error(`${path} failed with HTTP ${response.status}: ${detail}`);
      }
      return parsed;
    }

    // Attachments - mirrors the real form's attachment popup (HRM-TND45-MVC
    // TrainingNeedViewModel.js), one file at a time: each file is checked when it's picked
    // (SelectMainFile - type/size against #tndHdnFileTypes/#tndHdnFileSize), uploaded straight
    // away with TNDV9/TrainingNeed/UploadFile (UploadMainFile - one call per file, as in
    // T and D/Valid file/UploadFile.txt) and added to AttchList, and taken off with
    // TNDV9/TrainingNeed/DeleteFile (RemoveAttachment). Save then just sends AttchList.
    //
    // Runs on EVERY call, before anything can return early, so a file is never missed just
    // because the call that saw it ended at the goal list or a need question. A file is
    // uploaded on the call that first sees it - while the chat still hands over its
    // contents - so the confirming call submits what's already on the server and never
    // needs the file again.
    //
    // BeaconBar.getUploadedBaoFiles() lists every file attached in the conversation and keeps
    // listing a file after it has been dealt with (a rejected images.png came back on every
    // later call). Seen live in Lexi (attachmentCheck): the list is NEWEST first, and only
    // the files of the current message come with their contents - earlier ones are {name,
    // key} stubs. So positions shift with every attachment and can't be used to tell new
    // files from old ones. A listed file is new when either:
    //   - its name is listed more times than on the previous call (re-attaching the very
    //     same file adds another copy), or
    //   - it comes with readable contents and this tool hasn't seen that file object before
    //     (a file of the current message - this also catches a new chat in the same page
    //     whose first file has a name the previous chat already had).
    // Files already dealt with are never processed again, whatever order the chat lists
    // them in; of several copies of one name, an unseen readable copy is taken as the new
    // one. A name listed fewer times than before means a different conversation in the same
    // page, and the tracking starts over; uploaded files whose name the chat no longer lists
    // at all belong to another conversation and are dropped from this application.
    //
    // Page state (window.__peoplesHRTndSelfNeedUploads), kept until the application is saved:
    //   chatCounts  - lower-cased name -> how many times the chat listed it on the last call
    //   seenObjects - every file object this tool has already looked at (WeakSet)
    //   staged      - files uploaded for this application: { key, name, type, size, filepath }
    //   leftOut     - lower-cased name -> { name, reason: "removed" | "replaced" | "rejected" }
    //   unavailable - lower-cased name -> name: listed as new, but without readable contents
    const lc = (n) => String(n || "").trim().toLowerCase();

    async function chatEntries() {
      try {
        if (typeof BeaconBar !== "undefined" && typeof BeaconBar.getUploadedBaoFiles === "function") {
          // Awaited like collectChatAttachment does - harmless if it returns a plain value.
          const bao = await BeaconBar.getUploadedBaoFiles();
          return (Array.isArray(bao) ? bao : (bao ? [bao] : [])).filter((f) => f && typeof f === "object" && f.name);
        }
      } catch (e) {
        // Degrade to "no files" rather than throw.
      }
      return [];
    }

    // The chat doesn't always hand over a Blob (the benefit tools saw a wrapper describing
    // the file instead), so whatever arrives - a File, a wrapper holding one, raw bytes,
    // base64, a data: URL or a link - is turned into a Blob, or null if it has no contents.
    function base64ToBlob(text, type) {
      const clean = String(text).replace(/^data:[^,]*,/, "").replace(/\s/g, "");
      const binary = atob(clean);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      return new Blob([bytes], type ? { type: type } : undefined);
    }

    async function fileBlobOf(entry) {
      const type = entry.type || entry.mimeType || entry.contentType || "";
      if (typeof Blob !== "undefined" && entry instanceof Blob) return entry;
      const nested = entry.file || entry.blob || entry.rawFile || entry.originFileObj || entry.fileObject || entry.baoFile;
      if (nested && typeof Blob !== "undefined" && nested instanceof Blob) return nested;
      if (typeof entry.arrayBuffer === "function") {
        return new Blob([await entry.arrayBuffer()], type ? { type: type } : undefined);
      }
      const raw = entry.base64 || entry.base64Data || entry.Base64Data || entry.content || entry.fileData
        || entry.data || entry.bytes || entry.buffer || entry.url || entry.src || entry.fileUrl || entry.downloadUrl;
      if (raw && (raw instanceof ArrayBuffer || ArrayBuffer.isView(raw))) {
        return new Blob([raw], type ? { type: type } : undefined);
      }
      if (typeof raw === "string" && raw) {
        if (/^https?:\/\//i.test(raw) || raw.charAt(0) === "/") {
          const res = await fetch(raw, { redirect: "follow" });
          return await res.blob();
        }
        try { return base64ToBlob(raw, type); } catch (e) { return null; }
      }
      return null;
    }

    const cacheHost = typeof window !== "undefined" ? window : globalThis;
    const attachmentState = cacheHost.__peoplesHRTndSelfNeedUploads = cacheHost.__peoplesHRTndSelfNeedUploads || {};
    attachmentState.chatCounts = attachmentState.chatCounts || {};
    attachmentState.seenObjects = attachmentState.seenObjects || new WeakSet();
    attachmentState.staged = attachmentState.staged || [];
    attachmentState.leftOut = attachmentState.leftOut || {};
    attachmentState.unavailable = attachmentState.unavailable || {};

    // Each listed file with its contents resolved (null for a {name, key} stub).
    const listed = [];
    for (const entry of await chatEntries()) {
      let blob = null;
      try {
        blob = await fileBlobOf(entry);
      } catch (readError) {
        blob = null;
      }
      listed.push({
        entry: entry,
        name: String(entry.name),
        key: lc(entry.name),
        blob: blob && blob.size ? blob : null,
        unseen: !attachmentState.seenObjects.has(entry)
      });
    }
    listed.forEach((f) => attachmentState.seenObjects.add(f.entry));

    const chatCounts = {};
    listed.forEach((f) => { chatCounts[f.key] = (chatCounts[f.key] || 0) + 1; });
    let previousCounts = attachmentState.chatCounts;
    if (Object.keys(previousCounts).some((k) => (chatCounts[k] || 0) < previousCounts[k])) {
      attachmentState.staged = [];
      attachmentState.leftOut = {};
      attachmentState.unavailable = {};
      previousCounts = {};
    }
    attachmentState.chatCounts = chatCounts;
    attachmentState.staged = attachmentState.staged.filter((s) => chatCounts[s.key]);
    Object.keys(attachmentState.leftOut).forEach((k) => { if (!chatCounts[k]) delete attachmentState.leftOut[k]; });
    Object.keys(attachmentState.unavailable).forEach((k) => { if (!chatCounts[k]) delete attachmentState.unavailable[k]; });

    // The chat lists newest first, so this is reversed to upload oldest first and keep the
    // files in the order they were attached.
    const freshness = (f) => (f.blob && f.unseen ? 2 : (f.blob ? 1 : 0));
    const newEntries = [];
    Object.keys(chatCounts).forEach((k) => {
      const copies = listed.filter((f) => f.key === k);
      const addedCopies = chatCounts[k] - (previousCounts[k] || 0);
      const currentMessageCopies = copies.filter((f) => freshness(f) === 2).length;
      const count = Math.max(addedCopies, currentMessageCopies);
      if (count <= 0) return;
      copies.sort((a, b) => freshness(b) - freshness(a));
      newEntries.push(...copies.slice(0, count));
    });
    newEntries.sort((a, b) => listed.indexOf(b) - listed.indexOf(a));

    const removeNames = (Array.isArray(args.removeAttachments)
      ? args.removeAttachments
      : (args.removeAttachments ? [args.removeAttachments] : []))
      .map(lc)
      .filter(Boolean);
    const replaceAttachments = args.replaceAttachments === true || String(args.replaceAttachments).toLowerCase() === "true";

    // Same resource keys the form alerts with, fetched live like every other GetTndResource
    // string in this tool; the fallbacks are the captured responses.
    async function tndResource(resource, fallback) {
      try {
        const text = await postJson("TNDV9/Common/GetTndResource", { resource: resource });
        if (typeof text === "string" && text.trim()) return text.trim();
      } catch (resourceError) {
        // Keep the fallback - this lookup is best-effort only.
      }
      return fallback;
    }

    // DeleteFile always answers "true" (TrainingNeedController.DeleteFile swallows errors),
    // so this is best-effort, the same as the form's RemoveAttachment.
    async function deleteStaged(entry) {
      try {
        await postJson("TNDV9/TrainingNeed/DeleteFile", { filepath: entry.filepath });
      } catch (deleteError) {
        // Leaves a stray file server-side at worst; it's no longer on the application.
      }
    }

    const attachmentNotes = [];
    const rejectedNow = [];
    const stagedNow = [];
    let attachmentLimits = null;

    if (newEntries.length) {
      // TNDLibrary.GetMaxFileSize()/GetfileTypes()'s own defaults - only used if the page
      // can't be read. The form compares the extension with indexOf against the raw
      // comma-separated string, which would also accept a fragment like "df" (inside "pdf") -
      // compared against the split list here instead. Size is checked before type, the same
      // order as the form.
      attachmentLimits = { maxFileSizeMb: 3, allowedFileTypes: ["doc", "docx", "pdf", "xls", "xlsx", "jpeg", "jpg", "txt", "bmp", "rtf"] };
      try {
        const indexRes = await fetch(`${window.origin}/${reqOptions.sl}/TNDV9/TrainingNeed/Index?mvc=1&bs=4&App=000001`, {
          method: "GET",
          headers: { "Accept": "*/*", "x-requested-with": "XMLHttpRequest" }
        });
        if (indexRes.ok) {
          const indexDoc = new DOMParser().parseFromString(await indexRes.text(), "text/html");
          const pageMaxSize = parseFloat(indexDoc.querySelector("#tndHdnFileSize")?.value || "");
          const pageFileTypes = (indexDoc.querySelector("#tndHdnFileTypes")?.value || "")
            .split(",")
            .map((t) => t.trim().replace(/^\./, "").toLowerCase())
            .filter(Boolean);
          if (pageMaxSize > 0) attachmentLimits.maxFileSizeMb = pageMaxSize;
          if (pageFileTypes.length) attachmentLimits.allowedFileTypes = pageFileTypes;
        }
      } catch (settingsError) {
        // Keep the defaults above.
      }

      for (const newFile of newEntries) {
        const fileName = newFile.name;
        const key = newFile.key;
        const blob = newFile.blob;
        if (removeNames.includes(key)) {
          continue; // Attached and removed in the same breath - never uploaded.
        }
        if (!blob) {
          attachmentState.unavailable[key] = fileName;
          continue;
        }

        const dotIndex = fileName.lastIndexOf(".");
        const fileType = dotIndex >= 0 ? fileName.slice(dotIndex + 1).toLowerCase() : "";
        if (blob.size > attachmentLimits.maxFileSizeMb * 1024 * 1024) {
          rejectedNow.push({ fileName: fileName, reason: "size", sizeMb: +(blob.size / (1024 * 1024)).toFixed(2) });
          attachmentState.leftOut[key] = { name: fileName, reason: "rejected" };
          continue;
        }
        if (!attachmentLimits.allowedFileTypes.includes(fileType)) {
          rejectedNow.push({ fileName: fileName, reason: "type", fileType: fileType });
          attachmentState.leftOut[key] = { name: fileName, reason: "rejected" };
          continue;
        }

        // Confirmed live (T and D/Valid file/UploadFile.txt, and Dev in progress Features/
        // T&D/UploadFile, UploadFile-2, UploadFile-3 for three files in one application):
        // multipart/form-data with "fname" (a ddMMyyyyHHmmss_ timestamp prefix plus the
        // original file name, which becomes the server-side filepath AttchList references)
        // and "file" (the binary itself); the endpoint answers with the plain text "True".
        const now = new Date();
        const pad = (n) => String(n).padStart(2, "0");
        const timestamp = `${pad(now.getDate())}${pad(now.getMonth() + 1)}${now.getFullYear()}${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
        const serverFileName = `${timestamp}_${fileName}`;
        const uploadFormData = new FormData();
        uploadFormData.append("fname", serverFileName);
        uploadFormData.append("file", blob, fileName);

        let uploadText = "";
        try {
          const uploadRes = await fetch(`${window.origin}/${reqOptions.sl}/TNDV9/TrainingNeed/UploadFile`, {
            method: "POST",
            headers: { "Accept": "*/*", "x-requested-with": "XMLHttpRequest" },
            body: uploadFormData
          });
          uploadText = (await uploadRes.text()).trim();
        } catch (networkError) {
          uploadText = "";
        }
        if (uploadText.toLowerCase() !== "true") {
          // UploadFile does no type/size checking of its own (TrainingNeedController.
          // UploadFile saves whatever it receives and returns true, or false when no file
          // arrived), so this means the upload itself failed. Files already uploaded stay
          // on the application.
          return {
            status: "ERROR",
            message: `Could not upload "${fileName}"${uploadText && uploadText.toLowerCase() !== "false" ? `: ${uploadText}` : " - the server did not accept the file."} Nothing has been submitted. Ask the employee to attach the file again, then call this tool again with the same arguments.`,
            attachments: attachmentState.staged.map((s) => s.name)
          };
        }

        // Attaching a file under a name already on the application replaces that one file.
        const sameName = attachmentState.staged.findIndex((s) => s.key === key);
        const stagedEntry = { key: key, name: fileName, type: fileType, size: blob.size, filepath: serverFileName };
        if (sameName >= 0) {
          await deleteStaged(attachmentState.staged[sameName]);
          attachmentState.staged[sameName] = stagedEntry;
        } else {
          attachmentState.staged.push(stagedEntry);
        }
        delete attachmentState.leftOut[key];
        delete attachmentState.unavailable[key];
        stagedNow.push(key);
      }
    }

    // replaceAttachments: the file(s) uploaded on this call replace every earlier one.
    if (replaceAttachments) {
      if (stagedNow.length) {
        const replaced = attachmentState.staged.filter((s) => !stagedNow.includes(s.key));
        for (const s of replaced) {
          await deleteStaged(s);
          attachmentState.leftOut[s.key] = { name: s.name, reason: "replaced" };
        }
        attachmentState.staged = attachmentState.staged.filter((s) => stagedNow.includes(s.key));
        if (replaced.length) {
          attachmentNotes.push(`${replaced.map((s) => `"${s.name}"`).join(", ")} ${replaced.length === 1 ? "was" : "were"} replaced and will not be submitted.`);
        }
      } else {
        attachmentNotes.push("replaceAttachments was set, but no new file was attached in this message, so nothing was replaced. To take an earlier file off, pass its name in removeAttachments instead.");
      }
    }

    // removeAttachments: off the application and deleted from the server, like the form's
    // RemoveAttachment. Attaching the file again brings it back.
    const notAttached = [];
    for (const key of removeNames) {
      const stagedIndex = attachmentState.staged.findIndex((s) => s.key === key);
      if (stagedIndex >= 0) {
        const s = attachmentState.staged[stagedIndex];
        await deleteStaged(s);
        attachmentState.staged.splice(stagedIndex, 1);
        attachmentState.leftOut[key] = { name: s.name, reason: "removed" };
      } else if (attachmentState.unavailable[key]) {
        attachmentState.leftOut[key] = { name: attachmentState.unavailable[key], reason: "removed" };
        delete attachmentState.unavailable[key];
      } else if (!attachmentState.leftOut[key]) {
        notAttached.push(key);
      }
    }
    if (notAttached.length) {
      attachmentNotes.push(`${notAttached.map((n) => `"${n}"`).join(", ")} ${notAttached.length === 1 ? "is" : "are"} not on this application, so nothing was removed for ${notAttached.length === 1 ? "it" : "them"}. Use the file names exactly as shown in preview.attachments.`);
    }

    // What the chat handed over on this call - lets a live test see whether a newly attached
    // file actually reached the tool.
    const attachmentCheck = {
      filesListedByChat: listed.map((f) => f.name),
      withContentsOnThisCall: listed.filter((f) => f.blob).map((f) => f.name),
      newOnThisCall: newEntries.map((f) => f.name)
    };

    if (rejectedNow.length) {
      const sizeMessage = rejectedNow.some((r) => r.reason === "size")
        ? await tndResource("TndFileSizeExceeded", "Maximum file size exceeded.")
        : "";
      const typeMessage = rejectedNow.some((r) => r.reason === "type")
        ? await tndResource("TndFileTypeNotAllowed", "File type not allowed")
        : "";
      return {
        status: "VALIDATION_ERROR",
        message: "One or more attached files can't be added to this training need application. Tell the employee which file(s) were rejected and why, including the allowed file types and maximum size below. The rejected file(s) were not uploaded and are ignored from now on - do not put them in removeAttachments, and never tell the employee to start a new chat. Files in attachmentsKept are still attached. Nothing has been submitted. Ask the employee to attach a file that meets these limits, or to continue without it, then call this tool again with the same arguments on whatever they reply.",
        rejectedAttachments: rejectedNow.map((r) => ({
          fileName: r.fileName,
          reason: r.reason === "size"
            ? `${sizeMessage} The file is ${r.sizeMb} MB; the maximum is ${attachmentLimits.maxFileSizeMb} MB per file.`
            : `${typeMessage} (${r.fileType ? "." + r.fileType : "no file extension"}).`
        })),
        attachmentsKept: attachmentState.staged.map((s) => s.name),
        allowedFileTypes: attachmentLimits.allowedFileTypes,
        maxFileSizeMb: attachmentLimits.maxFileSizeMb,
        attachmentCheck: attachmentCheck
      };
    }

    // FEATURE ADD (2026-09-14): mirrors the real form's "Enable Goal Objectives" checkbox,
    // which loads the employee's ongoing performance goals straight into the Objectives
    // dropdown (see the screenshot in the request that prompted this) - previously this
    // tool only ever fetched GetOngoingGoals internally to resolve an already-known
    // goalTitle by exact match; there was no way for the employee to browse the list
    // first. When enableGoalObjectives is true and goalTitle hasn't been chosen yet, fetch
    // and return the list directly - deliberately BEFORE existingNeedName/newNeedName is
    // required, since picking a goal is independent of picking a need on the real form.
    // GetOngoingGoals never writes anything, so this is always safe to call standalone.
    if (enableGoalObjectives && !goalTitle) {
      const goalsData = await postJson("TNDV9/TrainingNeed/GetOngoingGoals", undefined);
      const ongoingGoals = (Array.isArray(goalsData) ? goalsData : []).map((g) => ({
        goalTitle: g.GoalTitle || "",
        goalCode: g.GoalCode
      }));
      return {
        status: "GOALS_LISTED",
        message: ongoingGoals.length > 0
          ? "Here are the employee's ongoing performance goals. Present the titles and ask which one to link as this training need's objective, then call this tool again with goalTitle set to their exact choice (along with existingNeedName/newNeedName and the other required fields)."
          : "The employee has no ongoing performance goals to link right now - use the objective argument instead for a free-text objective.",
        ongoingGoals: ongoingGoals
      };
    }

    if (!existingNeedName && !newNeedName) {
      return {
        status: "VALIDATION_ERROR",
        message: "Provide either existingNeedName (to attach this application to an existing training need - see getSelfTrainingNeeds) or newNeedName (to submit a brand new one), not neither."
      };
    }
    if (existingNeedName && newNeedName) {
      return {
        status: "VALIDATION_ERROR",
        message: "Provide either existingNeedName or newNeedName, not both - the real form's Training Need Type is either 'Existing Need' or 'New Need', never both at once."
      };
    }

    // Step 1: fetch the existing-need master list (MainNeed) and the self "subordinate"
    // record (SuborList[0]) - confirmed live: for the Applicant persona, GetTrainingNeedDetails'
    // SuborList contains exactly one entry, the logged-in employee's own record with
    // selected: 1 already set, the same "self is the only entry" pattern
    // selfEmployeeTrainingApplication's SubList[0] and getSelfTrainingNeeds already rely on.
    // This record is what gets echoed back (trimmed to a specific field subset - see Step 6)
    // as the outgoing EmpList entry - confirmed live via a real submitted payload.
    const detailsData = await postJson("TNDV9/TrainingNeed/GetTrainingNeedDetails", { requestType: "000001", WFMainID: "", PerfEmpNo: "" });
    if (!detailsData || !detailsData.Status || detailsData.Status.IsSuccessfull !== true) {
      return {
        status: "ERROR",
        message: (detailsData && detailsData.Status && detailsData.Status.Message) || "Failed to load the training need application form"
      };
    }
    const mainNeed = Array.isArray(detailsData.MainNeed) ? detailsData.MainNeed : [];
    const selfRecord = Array.isArray(detailsData.SuborList) ? detailsData.SuborList[0] : null;
    if (!selfRecord) {
      return {
        status: "ERROR",
        message: "Could not resolve the logged-in employee's own record from the training need application form."
      };
    }

    // Step 2: fetch the employee's ongoing performance goals - confirmed live, called again
    // (fresh) every time the real "Add" button is pressed on the form, feeding both the
    // goal-picker dropdown (when 'Enable Goal Objectives' is checked) and the ExistingGoals
    // field that's echoed back verbatim in the submission payload regardless of which mode
    // is used. Also re-fetched here (not just reused from the standalone listing branch
    // above) since this call may be reached directly with goalTitle already known, without
    // ever going through the listing branch first.
    const goalsData = await postJson("TNDV9/TrainingNeed/GetOngoingGoals", undefined);
    const existingGoals = Array.isArray(goalsData) ? goalsData : [];

    // Step 3: resolve the Training Need Type selection - Existing (typecode 1, a real
    // needcode, blank needname/needdescription) or New (typecode 0, needcode "000000",
    // free-text needname/needdescription) - confirmed live from both a real "existing need"
    // and a real "new need" submission capture.
    let typecode;
    let needcode;
    let needname;
    let needdescription;
    if (existingNeedName) {
      const lowerNeedName = existingNeedName.toLowerCase();
      const matches = mainNeed.filter((n) => (n.needname || "").toLowerCase().includes(lowerNeedName));
      if (matches.length === 0) {
        return {
          status: "ERROR",
          message: `No existing training need matching "${args.existingNeedName}" was found. Use getSelfTrainingNeeds to see what's currently on file, or pass newNeedName to submit a new one.`
        };
      }
      if (matches.length > 1) {
        return {
          status: "AMBIGUOUS",
          message: `More than one existing training need matches "${args.existingNeedName}".`,
          ambiguousField: "existingNeedName",
          candidates: matches.map((n) => ({ needCode: n.needcode, needName: n.needname }))
        };
      }
      typecode = 1;
      needcode = matches[0].needcode;
      needname = "";
      needdescription = "";
    } else {
      typecode = 0;
      needcode = "000000";
      needname = newNeedName;
      needdescription = newNeedDescription;
    }

    // Step 4: resolve the objective - either free text, or (when 'Enable Goal Objectives'
    // is used) linked to one of the employee's ongoing goals. Confirmed live: when
    // IsGoalObject is true, the literal "objective" field is sent blank and
    // SelectedGoalCode carries the real value instead - the server's "Please specify the
    // objective." validation covers both cases (a blank text objective, or a blank/unset
    // SelectedGoalCode), so only one of the two needs to be populated.
    let isGoalObject = false;
    let finalObjective = objective;
    let selectedGoalCode = null;
    if (goalTitle) {
      const lowerGoalTitle = goalTitle.toLowerCase();
      const goalMatches = existingGoals.filter((g) => (g.GoalTitle || "").trim().toLowerCase() === lowerGoalTitle);
      if (goalMatches.length === 0) {
        return {
          status: "ERROR",
          message: `No ongoing goal titled "${args.goalTitle}" was found. Call this tool again with enableGoalObjectives: true (and no goalTitle) to see the current list, or provide the objective argument instead for a free-text objective.`
        };
      }
      if (goalMatches.length > 1) {
        return {
          status: "AMBIGUOUS",
          message: `More than one ongoing goal is titled "${args.goalTitle}" - they can't be told apart by title alone. Provide the objective argument instead to enter a free-text objective.`,
          ambiguousField: "goalTitle"
        };
      }
      isGoalObject = true;
      finalObjective = "";
      selectedGoalCode = goalMatches[0].GoalCode;
    }

    // Step 5: attachments - the files uploaded by the attachment handling at the top of this
    // call (and of earlier calls for this application) are this application's attachments.
    // Entirely optional: with no files attached, Attach/FileNameAttached/AttchList stay at
    // their original "no attachment" values below. Each file was already checked against
    // the form's type/size limits before it was uploaded.
    const attchList = [];

    // Step 6: confirmation gate - confirmed live via TNDV9/Common/GetTndResource
    // ({resource: "TndNeedApplicationSaveConfirm"} -> "Are you sure you want to submit
    // this training need?"): the real form always shows this confirm dialog right before
    // Save, after every field has already been filled in. Nothing is validated or saved
    // until the employee has reviewed this exact application and confirmed. Attached files
    // are already uploaded at this point, as on the real form (UploadFile runs when a file
    // is added, not on Save), and only become part of a training need once Save references
    // them in AttchList. The prompt text is fetched live rather than hardcoded - it's just
    // another GetTndResource-owned string that can change server-side.
    if (!args.confirmed) {
      let confirmPrompt = "Are you sure you want to submit this training need?";
      try {
        const promptResource = await postJson("TNDV9/Common/GetTndResource", { resource: "TndNeedApplicationSaveConfirm" });
        if (typeof promptResource === "string" && promptResource.trim()) {
          confirmPrompt = promptResource.trim();
        }
      } catch (resourceError) {
        // Keep the fallback text above - this lookup is best-effort only.
      }

      const unavailableNames = Object.keys(attachmentState.unavailable).map((k) => attachmentState.unavailable[k]);
      return {
        status: "CONFIRMATION_REQUIRED",
        message: `Review this training need application with the employee before submitting, listing preview.attachments exactly - these are the only files that will be submitted. ${confirmPrompt} Call this tool again with confirmed:true (and the same arguments) once they agree. If they want to change the attachments first: a newly attached file is added (several files are allowed); to take a file off, call again with removeAttachments; to swap the earlier files for the one(s) attached in the current message, call again with replaceAttachments: true. Whenever the user attaches another file, call this tool again on that same turn (same arguments) - never just acknowledge it, since the chat hands over a file's contents only on the turn it was attached.`,
        confirmationPrompt: confirmPrompt,
        preview: {
          needSelectionType: existingNeedName ? "Existing" : "New",
          needName: existingNeedName ? mainNeed.find((n) => n.needcode === needcode).needname : newNeedName,
          objective: isGoalObject ? null : finalObjective,
          linkedGoalTitle: isGoalObject ? goalTitle : null,
          relevanceToJob: relevanceToJob,
          benefitToEmployee: benefitToEmployee,
          benefitToCompany: benefitToCompany,
          attachments: attachmentState.staged.map((a) => ({ fileName: a.name })),
          attachmentsLeftOut: Object.keys(attachmentState.leftOut).map((k) => ({ fileName: attachmentState.leftOut[k].name, reason: attachmentState.leftOut[k].reason })),
          attachmentsUnavailable: unavailableNames
        },
        attachmentNotes: attachmentNotes.concat(unavailableNames.length
          ? [`${unavailableNames.map((n) => `"${n}"`).join(", ")} ${unavailableNames.length === 1 ? "was" : "were"} attached on an earlier turn that this tool was not called on, so ${unavailableNames.length === 1 ? "its" : "their"} contents can no longer be read and ${unavailableNames.length === 1 ? "it is" : "they are"} not on the application. Ask the employee to attach only ${unavailableNames.length === 1 ? "that file" : "those files"} again, and call this tool on the turn ${unavailableNames.length === 1 ? "it is" : "they are"} attached. The files in preview.attachments are already uploaded - never ask for them again or ask for all files to be attached together.`]
          : []),
        attachmentCheck: attachmentCheck
      };
    }

    // Step 7: attachments - only reached once the employee has confirmed above. The files
    // were uploaded when they were attached (see the attachment handling at the top), so
    // AttchList just references them by their server-side filepath - the same entries the
    // form pushes in UploadMainFile ({attchid, attchname, attchtype, attchfile: "",
    // filepath}). Confirmed live that multiple entries are accepted
    // (SaveNeedApplication-round2's 3-entry AttchList).
    attachmentState.staged.forEach((a, i) => {
      attchList.push({
        attchid: i + 1,
        attchname: a.name,
        attchtype: a.type,
        attchfile: "",
        filepath: a.filepath
      });
    });

    // Step 8: build the outgoing EmpList entry - a specific field subset of the self
    // record (not the whole SuborList object), confirmed live by direct comparison against
    // a real submitted payload (it omits reqtypecode/editable, which SuborList itself
    // carries) - selected is always 1 for the self applicant.
    const empListEntry = {
      tna_id: selfRecord.tna_id,
      raw_id: selfRecord.raw_id,
      empno: selfRecord.empno,
      displayempno: selfRecord.displayempno,
      empname: selfRecord.empname,
      designame: selfRecord.designame,
      app_approved: selfRecord.app_approved,
      typecode: selfRecord.typecode,
      selected: 1,
      enrollstatus: selfRecord.enrollstatus,
      appid: selfRecord.appid,
      schmode: selfRecord.schmode,
      course: selfRecord.course,
      SchList: Array.isArray(selfRecord.SchList) ? selfRecord.SchList : [],
      EvalList: Array.isArray(selfRecord.EvalList) ? selfRecord.EvalList : []
    };

    // Step 9: build the submission payload - every fixed field below (needtype, status,
    // appdate/Strappdate, projectcode, supcomment, app_person, app_approved, wfmainid,
    // wfsequence, rejectcomment, centrecode, reqtypename, editable, enrollstatus, appid,
    // newneed, disableneeds, Attach, FileNameAttached) is confirmed identical across both
    // a real "existing need" and a real "new need" submission capture - newneed is always 1
    // here (it marks this as a new application RECORD, unrelated to the Existing/New Need
    // Type choice, which is typecode). Attach stays "0" and FileNameAttached stays "" even
    // when files ARE attached - confirmed live (Dev in progress Features/T&D/
    // ValidateNeedApplication, SaveNeedApplication with a real attachment): the module links
    // attachments purely through AttchList, which is now populated from Step 7 above.
    const payload = {
      tna_id: -1,
      needtype: "",
      typecode: typecode,
      needname: needname,
      needdescription: needdescription,
      status: "Pending",
      appdate: null,
      Strappdate: null,
      objective: finalObjective,
      projectcode: "",
      supcomment: "",
      app_person: "",
      app_approved: 0,
      wfmainid: "",
      wfsequence: 0,
      rejectcomment: "",
      centrecode: "",
      reltojob: relevanceToJob,
      potentialyou: benefitToEmployee,
      potentialcomp: benefitToCompany,
      needcode: needcode,
      reqtypecode: "000001",
      reqtypename: "",
      editable: 1,
      enrollstatus: "",
      appid: 0,
      newneed: 1,
      disableneeds: 0,
      Attach: "0",
      FileNameAttached: "",
      EmpList: [empListEntry],
      AttchList: attchList,
      IsGoalObject: isGoalObject,
      ExistingGoals: existingGoals,
      SelectedGoalCode: selectedGoalCode
    };

    // Step 10: validate, then save - confirmed live two-step flow
    // (New_PeoplesHR_Feature/selfEmployeeTrainingNeedApplication/applicant - {existing,new}
    // need submission.txt), same validate-then-save convention as every other write tool
    // in this build. If validation or save fails, the uploaded files stay staged for this
    // application (page state is only cleared on success), so a retry submits them again
    // without re-uploading.
    const validation = await postJson("TNDV9/TrainingNeed/ValidateNeedApplication", payload);
    if (!validation || validation.IsSuccessfull !== true) {
      return {
        status: "VALIDATION_ERROR",
        message: (validation && validation.Message) || "The training need application was rejected during validation."
      };
    }

    const saveResult = await postJson("TNDV9/TrainingNeed/SaveNeedApplication", payload);
    if (!saveResult || saveResult.IsSuccessfull !== true) {
      return {
        status: "ERROR",
        message: (saveResult && saveResult.Message) || "Failed to submit the training need application."
      };
    }

    const resultEntry = (Array.isArray(saveResult.Results) && saveResult.Results[0]) || null;

    // The files are now part of the submitted application - they must not be deleted, and
    // the next application in this conversation starts with none. chatCounts is kept, so
    // the files already in the chat are not taken as new attachments again.
    attachmentState.staged = [];
    attachmentState.leftOut = {};
    attachmentState.unavailable = {};

    return {
      status: "SUCCESS",
      message: saveResult.Message || "Training need application submitted.",
      needSelectionType: existingNeedName ? "Existing" : "New",
      needCode: needcode,
      needName: existingNeedName ? mainNeed.find((n) => n.needcode === needcode).needname : newNeedName,
      submissionStatus: resultEntry ? resultEntry.status : null,
      attachments: attchList.map((a) => ({ fileName: a.attchname, type: a.attchtype }))
    };

  } catch (error) {
    const errorMessage = error && error.message ? error.message : String(error);
    return {
      status: "ERROR",
      message: `Failed to submit the training need application: ${errorMessage}`,
      error: errorMessage
    };
  }
})

